\cite[P. 367]{KM},\cite{Li-Ming}
\label{p1}
Let
$
\|A_1\|<1$ and $\displaystyle \mu (A_0)+\frac{\|A_0\|+\|A_1\|\|A_2\|}{1-\|A_1\|}<0$.

Then system \eqref{1.2a} is asymptotically stable.

\label{p2} \cite[P. 369]{KM} 
If $\|A_1\|+ h_2\|A_2\|<1$ and $$\displaystyle \mu (A_0+A_2)+\frac{\|A_0+A_2\|(\|A_1\|+h_2\|A_2\|)}{1-\|A_1\|- h_2\|A_2\|}<0$$
then system~\eqref{1.2a} is asymptotically stable.

\label{lemma2.1}
Let  
$\|A_0\|_{[t_0,\infty)}<1$, there exist an $\alpha_0 <0$ such that $\mu (C(t)+D(t))\leq \alpha_0$, 
$Z$ be a fundamental matrix of system \eqref{2.6}, and
\begin{equation}\label{2.7}

K_0:=                  
\frac{\|C\|_{[t_0,\infty)}+\sum_{k=0}^m \|D_k\|_{[t_0,\infty)}}{1-\|A_0\|_{[t_0,\infty)}}           

\left(\left\|\frac{A_0}{\mu(C+D)}\right\|_{[t_0,\infty)}+\sum_{k=0}^m  \tau_k \left\|\frac{D_k}{\mu(C+D)}\right\|_{[t_0,\infty)}\right)<1.

\end{equation}
Then,  $Z(t,s)$ satisfies 
\begin{equation}\label{2.5}
\|Z(t,s)\|\leq K, ~~t \geq s \geq t_0,
\end{equation}
where the bound $K$ is $K= (1-K_0)^{-1}$.

\label{lemma2.2}
Let  $\displaystyle \|A_0\|_{[t_0,\infty)}+\sum_{k=0}^m  \tau_k \|D_k\|_{[t_0,\infty)}<1$, $\mu (C(t)+D(t))\leq \alpha_0$ for some $\alpha_0 <0$, where $D$ from (\ref{D_def}) is used, $Z$ be a fundamental matrix of (\ref{2.6}), and the constant
\begin{equation*}


\displaystyle L_0:=  \displaystyle  \frac{\|C+D\|_{[t_0,\infty)}}{1-\|A_0\|_{[t_0,\infty)}-\sum_{k=0}^m  \tau_k \|D_k\|_{[t_0,\infty)}}   
\displaystyle \left(\left\|\frac{A_0}{\mu(C+D)}\right\|_{[t_0,\infty)}+\sum_{k=0}^m  \tau_k \left\|\frac{D_k}{\mu(C+D)}\right\|_{[t_0,\infty)}\right)<1.             
\end{equation*}
Then, $Z(t,s)$  satisfies (\ref{2.5}), where $L= (1-L_0)^{-1}$ is used instead of $K$.

\label{theorem3.1}
Let $\lambda$ and $\beta$ be positive constants for which
\begin{equation}\label{3.1}
\mu (P(t))\leq -\beta, \quad t \geq t_0, \quad e^{\lambda\sigma}\|A\|_{[t_0,\infty)}<1,
\end{equation}

\begin{equation}
\label{3.2}
\begin{array}{ll} 
M_1:=       
& \displaystyle         
\frac{\lambda +\sum\limits_{k=1}^m e^{\lambda\tau_k}\|B_k\|_{[t_0,\infty)}+\lambda e^{\lambda\sigma}\|A\|_{[t_0,\infty)}}{1-e^{\lambda\sigma}\|A\|_{[t_0,\infty)}}          
\vspace{2mm} \\                      
& \displaystyle  \times \left(\left\|\frac{A}{\mu (P)}\right\|_{[t_0,\infty)} \!\!\! \!\!\! \!\!\!\! (1+\lambda\sigma)e^{\lambda\sigma}
+\sum_{k=1}^m  \left\|\frac{ B_k}{\mu (P)}\right\|_{[t_0,\infty)} \!\!\!\!\!\!\!\!\!\! e^{\lambda\tau_k}\tau_k \right)<1,
\end{array}
\end{equation}
where $P$ is defined in \eqref{3.0}.

Then, for $M_0:=(1-M_1)^{-1}$, the solution of (\ref{2.1}),(\ref{2.2}) satisfies
\begin{equation}

\label{3.3}
\begin{array}{ll} \| x(t) \| \leq & \displaystyle M_0e^{-\lambda(t-t_0)}\left[  \| x(t_0)  \|
+\frac{e^{\lambda \sigma}-1}{\lambda(1-\|A\|_{[t_0,\infty)})} \|A\|_{[t_0,\infty)}\|\Psi\|_{[t_0-\sigma,t_0]}\right.          
\vspace{2mm}
\\
& \displaystyle \left.+\sum_{k=1}^m\frac{e^{\lambda \tau_k}-1}{\lambda(1-\|A\|_{[t_0,\infty)})}
 \|B_k\|_{[t_0,\infty)}\|\Phi\|_{[t_0-\tau_k,t_0]}\right]+\frac{M_0}{\lambda(1-\|A\|_{[t_0,\infty)})}\|f\|_{[t_0,t]}. \end{array}

\end{equation}

\label{theorem3.1a}
Let $\lambda$ and $\beta$ be positive constants for which
\begin{equation*}

\mu (P(t))\leq -\beta, \quad t \geq t_0, \quad  (1+\lambda  \sigma)e^{\lambda\sigma}\|A\|_{[t_0,\infty)}
+\sum_{k=1}^m \tau_k e^{\lambda\tau_k}\|B_k\|_{[t_0,\infty)}<1,
\end{equation*}

\begin{equation*}

\begin{array}{ll}	
M_2:= &                             
\frac{\lambda +\sum\limits_{k=1}^m e^{\lambda\tau_k}\|B_k\|_{[t_0,\infty)}+\lambda e^{\lambda\sigma}\|A\|_{[t_0,\infty)}}
{1-(1+\lambda  \sigma)e^{\lambda\sigma}\|A\|_{[t_0,\infty)}
-\sum_{k=1}^m \tau_k e^{\lambda\tau_k}\|B_k\|_{[t_0,\infty)}}          
\vspace{2mm} \\                      
& \displaystyle  \times \left(\left\|\frac{A}{\mu (P)}\right\|_{[t_0,\infty)}  \!\! \!\!\!\! (1+\lambda\sigma)e^{\lambda\sigma}
+\sum_{k=1}^m  \left\|\frac{ B_k}{\mu (P)}\right\|_{[t_0,\infty)} \!\!\!\!\! e^{\lambda\tau_k}\tau_k \right)<1,
\end{array}
\end{equation*}
where $P$ is defined in \eqref{3.0}.
Then the solution $x$ of (\ref{2.1}),(\ref{2.2}) satisfies \eqref{3.3} with $M_0:=(1-M_2)^{-1}$.

\label{corollary3.1}
Let $\lambda$ and $\beta$ be positive constants for which
\begin{equation}\label{3.6}
\mu (P_1(t))\leq -\beta, \quad t \geq t_0,\quad  e^{\lambda\sigma}\|A\|_{[t_0,\infty)}<1,
\end{equation}
\begin{equation}
\label{3.7}
M_3:=
\frac{\lambda +e^{\lambda\tau}\|B\|_{[t_0,\infty)}+\lambda e^{\lambda\sigma}\|A\|_{[t_0,\infty)}}{1-e^{\lambda\sigma}\|A\|_{[t_0,\infty)}} 
\left(\left\|\frac{A}{\mu (P_1)}\right\|_{[t_0,\infty)} \!\!\! \!\!\! \!\!\!\! (1+\lambda\sigma)e^{\lambda\sigma}
+ \left\|\frac{ B}{\mu (P_1)}\right\|_{[t_0,\infty)} \!\!\!\!\!\!\!\!\!\! e^{\lambda\tau}\tau \right)<1.
\end{equation}
Then for the solution $x$ of problem (\ref{3.5}),(\ref{2.2}) and $M_0:=(1-M_3)^{-1}$, we have 
\begin{equation}

\label{3.8}
\begin{array}{ll} \|x(t)\|\leq & \displaystyle M_0 e^{-\lambda(t-t_0)}\left[\|x(t_0)\|
+\frac{e^{\lambda \sigma}-1}{\lambda(1-\|A\|_{[t_0,\infty)})} \|A\|_{[t_0,\infty)}\| \Psi \|_{[t_0-\sigma,t_0]}\right.          
\vspace{2mm}
\\
& \displaystyle \left.+\frac{e^{\lambda \tau}-1}{\lambda(1-\|A\|_{[t_0,\infty)})} 
\|B\|_{[t_0,\infty)}\|\Phi\|_{[t_0-\tau,t_0]}\right]+\frac{M_0}{\lambda(1-\|A\|_{[t_0,\infty)})}\|f\|_{[t_0,t]}. \end{array}

\end{equation}

\label{corollary3.2}
Let $\lambda$ and $\beta$ be positive constants for which
$\mu (P_2(t))\leq -\beta$ for $t \geq t_0$ and
\begin{equation*}

M_4:=       
\left(\lambda +\sum\limits_{k=1}^m e^{\lambda\tau_k}\|B_k\|_{[t_0,\infty)}\right)                      
\sum_{k=1}^m  \left\|\frac{ B_k}{\mu (P_2)}\right\|_{[t_0,\infty)} \!\!\!\!\!\!\!\!\!\! e^{\lambda\tau_k}\tau_k <1.
\end{equation*}

Then, for $M_0:=(1-M_4)^{-1}$, the solution $x$ of problem (\ref{3.9}) satisfies
\begin{equation*}

 \|x(t)\|\leq \displaystyle M_0e^{-\lambda(t-t_0)}\left[\|x(t_0)\|
+\sum_{k=1}^m\frac{e^{\lambda \tau_k}-1}{\lambda} \|B_k\|_{[t_0,\infty)}\|\Phi\|_{[t_0-\tau_k,t_0]}\right]
+\frac{M_0}{\lambda}\|f\|_{[t_0,t]}.

\end{equation*}

\label{theorem3.2}
Let $\beta$ be a positive constant for which $\displaystyle B(t):=\sum_{k=1}^m B_k(t), ~\mu (B(t))\leq -\beta,~\|A\|_{[t_0,\infty)}<1$ and
\begin{equation}\label{3.12a}
\frac{\sum_{k=1}^m \|B_k\|_{[t_0,\infty)}}{1-\|A\|_{[t_0,\infty)}} 
\left(\left\|\frac{A}{\mu (B)}\right\|_{[t_0,\infty)}+\sum_{k=1}^m \tau_k\left\|\frac{B_k}{\mu (B)}\right\|_{[t_0,\infty)}\right)<1.
\end{equation}

Then equation (\ref{1.2}) is uniformly exponentially stable.

\label{corollary3.4}
Let $\beta$ be a positive constant for which $\mu (B(t))\leq - \beta$ for any $t \geq t_0$, where $\displaystyle B(t):=\sum_{k=1}^m B_k(t)$, and either
\\
\vspace{2mm}
1) $\displaystyle 

\sum_{k=1}^m \|B_k\|_{[t_0,\infty)}         

\sum_{k=1}^m \tau_k\left\|\frac{B_k}{\mu (B)}\right\|_{[t_0,\infty)}

<1$
\\
\vspace{2mm}
or
\\
\vspace{2mm}
2) $\displaystyle
\|B\|_{[t_0,\infty)} 

\sum_{k=1}^m \tau_k\left\|\frac{B_k}{\mu (B)}\right\|_{[t_0,\infty)}          
< 1-        
\sum_{k=1}^m \tau_k\left\|B_k\right\|_{[t_0,\infty)}$           
\\
\vspace{2mm}
is satisfied.
Then, system (\ref{3.9}) with $f\equiv 0$ is uniformly exponentially stable.

\label{corollary4.10}
Assume that for some $\beta>0,$ $\displaystyle b(t):= \sum_{k=1}^m b_k(t) \leq -\beta <0,~t\geq t_0$ and either 
\begin{equation}\label{4.11}
\sum_{k=1}^m\|b_k\|_{[t_0,\infty)}\left(\left\|\frac{a}{b}\right\|+\sum_{k=1}^m \tau_k \left\|\frac{b_k}{b}  \right\|\right)<1-\|a\|_{[t_0,\infty)}
\end{equation}
or
\begin{equation}\label{4.12}
\|b\|_{[t_0,\infty)}\left(\left\|\frac{a}{b}\right\|
+\sum_{k=1}^m \tau_k \left\|\frac{b_k}{b}\right\|\right)<1-\|a\|_{[t_0,\infty)}-\sum_{k=1}^m \tau_k \|b_k\|.
\end{equation}
Then equation \eqref{4.10} is uniformly exponentially stable.

\label{corollary4.1}
Assume that for some $\beta>0$, $\mu(A_0(t)+A_2(t))\leq -\beta<0, ~t\geq t_0$  
and at least one of the following  conditions holds:

\begin{equation}\label{4.1}
\displaystyle
\|A_1\|_{[t_0,\infty)}<1,~ -\beta+\frac{(\|A_0\|_{[t_0,\infty)}
+\|A_2\|_{[t_0,\infty)})(\|A_1\|_{[t_0,\infty)}+h_2\|A_2\|_{[t_0,\infty)})}{1-\|A_1\|_{[t_0,\infty)}}<0;
\end{equation}

\begin{equation}\label{4.2}
\displaystyle
\|A_1\|_{[t_0,\infty)}+h_2\|A_2\|_{[t_0,\infty)}<1,~ 
-\beta+\frac{\|A_0+A_2\|_{[t_0,\infty)}(\|A_1\|_{[t_0,\infty)}
+h_2\|A_2\|_{[t_0,\infty)})}{1-\|A_1\|_{[t_0,\infty)}-h_2\|A_2\|_{[t_0,\infty)}}<0.
\end{equation}
Then equation \eqref{1.2b} is uniformly exponentially stable.

Assume first that \eqref{4.1} holds. We will apply Theorem \ref{theorem3.2} for $m=2$ to equation \eqref{1.2b}.
 Inequality \eqref{3.12a} for \eqref{1.2b} has the form
 $$
\frac{\|A_0\|_{[t_0,\infty)}+\|A_2\|_{[t_0,\infty)}}{1-\|A_1\|_{[t_0,\infty)}}
\left(\left\|\frac{A_1}{\mu(A_0+A_2)}\right\|_{[t_0,\infty)}
+h_2\left\|\frac{A_2}{\mu(A_0+A_2)}\right\|_{[t_0,\infty)}\right)<1,
$$
which, due to $|\mu(A_0(t)+A_2(t))| \geq \beta$, yields that
\begin{equation}\label{4.3}
\frac{\|A_0\|_{[t_0,\infty)}+\|A_2\|_{[t_0,\infty)}}{1-\|A_1\|_{[t_0,\infty)}}
\left(\|A_1\|_{[t_0,\infty)}+h_2\|A_2\|_{[t_0,\infty)}\right)<\beta.
\end{equation}
Inequality \eqref{4.3} is equivalent to the second inequality in \eqref{4.1}. 

All conditions of Theorem \ref{theorem3.2} hold for equation \eqref{1.2b}, hence this equation is uniformly exponentially stable.

The second part of the corollary follows from Theorem \ref{theorem3.2a} and is justified in a similar way.
